import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Narrows the customer list by name and by status. Both criteria must hold.
 *
 * @param name     text the first or last name must contain, term by term; blank matches everyone
 * @param statuses statuses to keep; empty keeps every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", EnumSet.noneOf(CustomerStatus.class));

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = statuses.isEmpty()
                ? EnumSet.noneOf(CustomerStatus.class)
                : EnumSet.copyOf(statuses);
    }

    /** Returns a predicate for this filter. Name terms are normalised once, not per customer. */
    public Predicate<Customer> predicate() {
        List<String> terms = terms(name);
        Set<CustomerStatus> wanted = Set.copyOf(statuses);
        return customer -> (wanted.isEmpty() || wanted.contains(customer.status()))
                && matchesEveryTerm(customer, terms);
    }

    /**
     * Splits the text on whitespace and folds each term for comparison. Case and accents are ignored.
     */
    private static List<String> terms(String text) {
        return Arrays.stream(fold(text).trim().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    private static boolean matchesEveryTerm(Customer customer, List<String> terms) {
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    /** Lower-cases and strips diacritics, so that {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(Objects.requireNonNull(text), Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
    }
}
