    private final MultiSelectComboBox<CustomerStatus> statusFilter = new MultiSelectComboBox<>("Status");
    private final Span summary = new Span();
    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
    private final ConfigurableFilterDataProvider<Customer, Void, CustomerFilter> dataProvider;
    private final int totalCustomers;

    /** True while the fields are being set from the URL, so the URL is not rewritten meanwhile. */
    private boolean readingUrl;

    /** The last filter counted, and its count. See {@link #countMatching(CustomerFilter)}. */
    private CustomerFilter countedFilter;
    private int countedMatching;

    public CustomerListView(CustomerService customerService) {
        this.customerService = customerService;

        this.dataProvider = DataProvider.<Customer, CustomerFilter>fromFilteringCallbacks(
                query -> customerService.list(
                        query.getOffset(),
                        query.getLimit(),
                        toSorts(query.getSortOrders()),
                        query.getFilter().orElse(CustomerFilter.NONE)).stream(),
                query -> countMatching(query.getFilter().orElse(CustomerFilter.NONE)))
                .withConfigurableFilter();
        this.totalCustomers = countMatching(CustomerFilter.NONE);

        configureFilters();
        configureGrid();

        setSizeFull();
        add(new H2("Customers"),
                new HorizontalLayout(nameFilter, statusFilter),
                summary,
                grid);

        applyFilter();
    }

